parameters.jsCode:
const crypto = require('crypto');
const item = $input.first();
const sig = item.json.headers['x-paystack-signature'];
const body = item.json.body;
const hash = crypto
  .createHmac('sha512', $env.PAYSTACK_SECRET)
  .update(JSON.stringify(body))
  .digest('hex');
if (sig !== hash) {
  throw new Error('Invalid Paystack signature');
}
if (body.event !== 'charge.success') {
  return []; // only settle successful charges
}
const d = body.data;
return [{
  json: {
    reference: d.reference,
    amount_kobo: d.amount,
    paid_at: d.paid_at || new Date().toISOString(),
    channel: 'paystack',
    student_id: d.metadata?.student_id,
    invoice_id: d.metadata?.invoice_id,
    guardian_id: d.metadata?.guardian_id,
    student_name: d.metadata?.student_name,
    raw: d
  }
}];

